HOOK_TIMEOUT = 30

def _hook_arg(a):
    "What a shell hook is told about one positional: an id where the object has one, else its text."
    return getattr(a, 'session_id', None) or getattr(a, 'id', None) or (a if isinstance(a, (str, int, float, dict, list, type(None))) else type(a).__name__)

def _shell_hook(event, command, match=''):
    "A hook that feeds `command` `{event, args, **kw}` as JSON and reads a JSON object back: `deny`, `args` or `result`; any other output is ignored."
    def hook(*args, **kw):
        name = kw.get('name') or (args[1] if len(args) > 1 else '')
        if match and not fnmatch.fnmatch(str(name), match): return None
        r = subprocess.run(command, shell=True, input=json.dumps(dict(event=event, args=[_hook_arg(a) for a in args], **kw), default=str),
                           capture_output=True, text=True, timeout=HOOK_TIMEOUT)
        out = r.stdout.strip()
        if not out.startswith('{'): return None
        d = json.loads(out)
        return d.get('deny') or d.get('args') or d.get('result')
    return hook

def shell_hooks(reg, path):
    "Register the hooks a `hooks.json` lists: `[{event, match, command}]`."
    path = Path(path)
    if not path.exists(): return reg
    try: entries = json.loads(path.read_text())
    except Exception as e:
        reg.notes.append(f'{path.name}: failed to load ({host_err(e)})')
        return reg
    n = 0
    for h in entries:
        ev, cmd = h.get('event'), h.get('command')
        if ev not in EVENTS or not cmd: reg.notes.append(f'{path.name}: skipped {h}'); continue
        reg.on(ev, _shell_hook(ev, cmd, h.get('match', ''))); n += 1
    reg.notes.append(f'{path.name}: {n} hook(s)')
    return reg

